import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { NotificationService } from '../services/notification.service';
import { FormsModule } from '@angular/forms'; // Import FormsModule
import { CommonModule } from '@angular/common'; // Import CommonModule

@Component({
  selector: 'app-register',
  standalone: true, // Add standalone: true
  imports: [
    FormsModule, // Add FormsModule here
    CommonModule // Add CommonModule for basic directives if needed elsewhere
  ],
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  name = '';
  email = '';
  password = '';
  confirmPassword = '';

  constructor(
    private authService: AuthService,
    private router: Router,
    private notificationService: NotificationService
  ) {}

  register(): void {
    if (this.password !== this.confirmPassword) {
      this.notificationService.error('Passwords do not match.');
      return;
    }
    this.authService.register(this.name, this.email, this.password, this.confirmPassword).subscribe({
      next: () => {
        this.router.navigate(['/login']);
        this.notificationService.success('Registration successful! Please log in.');
      },
      error: (err) => {
        console.error('Registration failed', err);
        this.notificationService.error('Registration failed. Please try again.');
      }
    });
  }
}
<body class="bg-neutral-100" style='font-family: "Plus Jakarta Sans", "Noto Sans", sans-serif;'>
<div class="relative flex size-full min-h-screen flex-col group/design-root overflow-x-hidden">
  <div class="layout-container flex h-full grow flex-col">
    <main class="flex flex-1 items-center justify-center py-8 px-4 sm:px-6 lg:px-8">
      <div class="w-full max-w-md space-y-8">
        <div class="bg-white p-8 shadow-xl rounded-xl">
          <h2 class="text-center text-3xl font-extrabold text-neutral-800 mb-2">Create your account</h2>
          <p class="text-center text-sm text-neutral-600 mb-8">
            Join us and start your journey.
          </p>
          <form class="space-y-6" (ngSubmit)="register()">
            <div>
              <label class="block text-sm font-medium text-neutral-700 pb-1.5" for="name">Full name</label>
              <input class="form-input block w-full rounded-lg border-neutral-300 bg-neutral-50 shadow-sm focus:border-neutral-500 focus:ring-neutral-500 h-12 p-3 text-base placeholder-neutral-400" id="name" name="name" placeholder="Your Name" required="" type="text" [(ngModel)]="name"/>
            </div>
            <div>
              <label class="block text-sm font-medium text-neutral-700 pb-1.5" for="email">Email address</label>
              <input autocomplete="email" class="form-input block w-full rounded-lg border-neutral-300 bg-neutral-50 shadow-sm focus:border-neutral-500 focus:ring-neutral-500 h-12 p-3 text-base placeholder-neutral-400" id="email" name="email" placeholder="you@example.com" required="" type="email" [(ngModel)]="email"/>
            </div>
            <div>
              <label class="block text-sm font-medium text-neutral-700 pb-1.5" for="password">Password</label>
              <input autocomplete="new-password" class="form-input block w-full rounded-lg border-neutral-300 bg-neutral-50 shadow-sm focus:border-neutral-500 focus:ring-neutral-500 h-12 p-3 text-base placeholder-neutral-400" id="password" name="password" placeholder="••••••••" required="" type="password" [(ngModel)]="password"/>
            </div>
            <div>
              <label class="block text-sm font-medium text-neutral-700 pb-1.5" for="confirmPassword">Confirm Password</label>
              <input autocomplete="new-password" class="form-input block w-full rounded-lg border-neutral-300 bg-neutral-50 shadow-sm focus:border-neutral-500 focus:ring-neutral-500 h-12 p-3 text-base placeholder-neutral-400" id="confirmPassword" name="confirmPassword" placeholder="••••••••" required="" type="password" [(ngModel)]="confirmPassword"/>
            </div>
            <div>
              <button class="" type="submit">
                Sign up
              </button>
            </div>
          </form>
          <p class="mt-8 text-center text-sm text-neutral-500">
            Already have an account?
            <a class="font-medium text-[#141414] hover:text-neutral-700 link-subtle" routerLink="/login">Log in</a>
          </p>
        </div>
      </div>
    </main>
  </div>
</div>
</body>
